G.ROOMS["zh-l308"] = {"id":"zh-l308","lang":"zh","level":5,"no":308,"teacher":"wang","title":"HSK5 · Bài 308 · 评价和行为 Đánh giá và hành vi","intro":["了解自己的短处，才能不断进步。","Bài 308: Nói về điểm yếu, có chứa, kịp/và, dựa vào, mạng sống, đánh giá, thủ đoạn, vở kịch, cục tẩy, hành vi, cần và giải trí. Bấm 1 · Học để bắt đầu."],"introPy":"Liǎojiě zìjǐ de duǎnchu, cái néng búduàn jìnbù.","gram":{"t":"V + 不及 / 得及","b":"来不及 · 来得及","d":"Kịp / không kịp làm gì.","ex":[["现在出发还来得及。","Xuất phát bây giờ vẫn còn kịp.","Xiànzài chūfā hái lái de jí."]]},"grams":[{"t":"V + 不及 / 得及","b":"来不及 · 来得及","d":"Kịp / không kịp làm gì.","ex":[["现在出发还来得及。","Xuất phát bây giờ vẫn còn kịp.","Xiànzài chūfā hái lái de jí."]]}],"items":[{"zh":"短处","py":"duǎnchu","vi":"điểm yếu","hv":"đoản xứ","note":"Trái nghĩa 长处 (điểm mạnh).","ex":"了解自己的短处，才能不断进步。","exPy":"Liǎojiě zìjǐ de duǎnchu, cái néng búduàn jìnbù.","exVi":"Hiểu điểm yếu của mình mới tiến bộ không ngừng.","w":"了解 自己 的 短处， 才能 不断 进步。"},{"zh":"含有","py":"hányǒu","vi":"có chứa","hv":"hàm hữu","note":"含有维生素 (có chứa vitamin).","ex":"这种饮料含有咖啡因。","exPy":"Zhè zhǒng yǐnliào hányǒu kāfēiyīn.","exVi":"Đồ uống này có chứa caffeine.","w":"这 种 饮料 含有 咖啡 因。"},{"zh":"及","py":"jí","vi":"và; kịp","hv":"cập","note":"来不及 (không kịp).","ex":"时间来不及了，快走吧！","exPy":"Shíjiān lái bu jí le, kuài zǒu ba!","exVi":"Không kịp giờ rồi, đi nhanh lên!","w":"时间 来不及 了， 快 走 吧！"},{"zh":"靠","py":"kào","vi":"dựa vào; tựa","hv":"kháo","note":"靠自己 (dựa vào chính mình).","ex":"成功只能靠自己。","exPy":"Chénggōng zhǐ néng kào zìjǐ.","exVi":"Thành công chỉ có thể dựa vào bản thân.","w":"成功 只能 靠 自己。"},{"zh":"命","py":"mìng","vi":"mạng sống; số phận","hv":"mệnh","note":"救命 (cứu mạng).","ex":"医生救了他的命。","exPy":"Yīshēng jiù le tā de mìng.","exVi":"Bác sĩ đã cứu mạng anh ấy.","w":"医生 救 了 他 的 命。"},{"zh":"评价","py":"píngjià","vi":"đánh giá","hv":"bình giá","note":"Chính là \"bình giá\".","ex":"别人的评价很重要，但更重要的是自己的努力。","exPy":"Biérén de píngjià hěn zhòngyào, dàn gèng zhòngyào de shì zìjǐ de nǔlì.","exVi":"Đánh giá của người khác quan trọng, nhưng quan trọng hơn là nỗ lực của bản thân.","w":"别人 的 评价 很 重要， 但 更 重要 的 是 自己 的 努力。"},{"zh":"手段","py":"shǒuduàn","vi":"cách thức, biện pháp","hv":"thủ đoạn","note":"Trung tính: biện pháp; xấu: thủ đoạn.","ex":"教育不能只靠批评的手段。","exPy":"Jiàoyù bù néng zhǐ kào pīpíng de shǒuduàn.","exVi":"Giáo dục không thể chỉ dựa vào cách phê bình.","w":"教育 不 能 只 靠 批评 的 手段。"},{"zh":"戏","py":"xì","vi":"kịch, tuồng; trò","hv":"hí","note":"看戏 (xem kịch), 京戏 (kinh kịch).","ex":"奶奶喜欢看京戏。","exPy":"Nǎinai xǐhuan kàn jīngxì.","exVi":"Bà nội thích xem kinh kịch.","w":"奶奶 喜欢 看 京 戏。"},{"zh":"橡皮","py":"xiàngpí","vi":"cục tẩy","hv":"tượng bì","note":"橡 là cao su.","ex":"我可以借你的橡皮吗？","exPy":"Wǒ kěyǐ jiè nǐ de xiàngpí ma?","exVi":"Tôi mượn cục tẩy của bạn được không?","w":"我 可以 借 你 的 橡皮 吗？"},{"zh":"行为","py":"xíngwéi","vi":"hành vi","hv":"hành vi","note":"Chính là \"hành vi\".","ex":"这种行为是不对的。","exPy":"Zhè zhǒng xíngwéi shì bú duì de.","exVi":"Hành vi này là sai.","w":"这 种 行为 是 不 对 的。"},{"zh":"需","py":"xū","vi":"cần","hv":"nhu","note":"Văn viết của 需要.","ex":"报名需带身份证。","exPy":"Bàomíng xū dài shēnfènzhèng.","exVi":"Đăng ký cần mang căn cước.","w":"报名 需 带 身份证。"},{"zh":"娱乐","py":"yúlè","vi":"giải trí","hv":"ngu lạc","note":"娱乐活动 (hoạt động giải trí).","ex":"电竞已经不只是娱乐，而是一种职业。","exPy":"Diànjìng yǐjīng bù zhǐ shì yúlè, ér shì yì zhǒng zhíyè.","exVi":"Thể thao điện tử không còn chỉ là giải trí, mà là một nghề.","w":"电 竞 已经 不 只是 娱乐， 而 是 一 种 职业。"}],"newChars":["橡","娱"],"outro":"很好！Xong bài 308."};
